export function getPublicServiceImages(sourceRecordId?: string | null, profileAsset?: string | null, coverAsset?: string | null) {
  const md = sourceRecordId
    || profileAsset?.match(/perix_md_\d{3}/)?.[0]
    || coverAsset?.match(/perix_md_\d{3}/)?.[0];
  if (md) return images[md] ?? null;
  const gar = sourceRecordId
    || profileAsset?.match(/perix_de_gar_\d{4}/)?.[0]
    || coverAsset?.match(/perix_de_gar_\d{4}/)?.[0];
  if (gar) return gardelegenImages[gar.replace("perix_de_gar_", "gar_")] ?? null;
  if (sourceRecordId && (sourceRecordId.startsWith("perix_aak_") || sourceRecordId.startsWith("perix_ach_")))
    return athensImages[sourceRecordId] ?? null;
  return null;
}
